/* Genere par dashboard/gen_page.py depuis dashboard.html : ne pas modifier a la main. */
static const char PAGE[] =
    "<!doctype html>\n"
    "<html lang=\"fr\"><head><meta charset=\"utf-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
    "<title>Tableau de bord PS5</title>\n"
    "<style>\n"
    ":root{--card:rgba(16,19,28,.88);--line:rgba(255,255,255,.08);--txt:#eef1f7;--mut:#9aa3b5;--acc:#3b82f6;--ok:#34d399;--bad:#f87171}\n"
    "*{box-sizing:border-box}\n"
    "body{margin:0;min-height:100vh;color:var(--txt);font:16px/1.4 system-ui,Segoe UI,Roboto,sans-serif;\n"
    "background:radial-gradient(1200px 700px at 20% -10%,#4a2b12 0%,transparent 60%),radial-gradient(900px 600px at 100% 0%,#7a3b10 0%,transparent 55%),#0b0d14}\n"
    "header{display:flex;align-items:baseline;justify-content:space-between;padding:22px 28px 6px}\n"
    "#clock{font-size:44px;font-weight:600;letter-spacing:1px}\n"
    "#date{color:var(--mut);margin-left:14px;font-size:17px;text-transform:capitalize}\n"
    "#ip{color:var(--mut);font-size:13px}\n"
    "main{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:14px 28px 40px;max-width:1300px;margin:auto}\n"
    ".card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px 18px;min-height:130px}\n"
    ".card h2{margin:0 0 10px;font-size:15px;font-weight:600;color:var(--mut);letter-spacing:.4px}\n"
    ".wide{grid-column:span 2}\n"
    ".big{font-size:34px;font-weight:600}\n"
    ".row{display:flex;justify-content:space-between;align-items:center;margin:6px 0}\n"
    ".bar{height:10px;border-radius:6px;background:rgba(255,255,255,.1);overflow:hidden;margin-top:10px}\n"
    ".bar>i{display:block;height:100%;background:var(--acc)}\n"
    ".pill{padding:2px 10px;border-radius:99px;font-size:13px;border:1px solid var(--line)}\n"
    ".sw{position:relative;width:46px;height:26px;border-radius:99px;background:rgba(255,255,255,.18);border:0;cursor:pointer;flex:none}\n"
    ".sw::after{content:\"\";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:.15s}\n"
    ".sw.on{background:var(--acc)}.sw.on::after{left:23px}.sw:disabled{opacity:.4}\n"
    ".on{color:var(--ok)}.off{color:var(--bad)}\n"
    "a.link{display:block;margin:6px 0;padding:10px 12px;border-radius:10px;background:rgba(255,255,255,.06);color:var(--txt);text-decoration:none}\n"
    "a.link:hover{background:rgba(59,130,246,.35)}\n"
    "small{color:var(--mut)}\n"
    "@media(max-width:900px){main{grid-template-columns:1fr}.wide{grid-column:auto}}\n"
    "</style></head><body>\n"
    "<header><div><span id=\"clock\">--:--</span><span id=\"date\"></span></div><div id=\"ip\"></div></header>\n"
    "<main>\n"
    " <section class=\"card\"><h2>STOCKAGE DE LA CONSOLE</h2><div id=\"storage\">...</div></section>\n"
    " <section class=\"card\"><h2>MÉTÉO</h2><div id=\"weather\"><small>Chargement…</small></div></section>\n"
    " <section class=\"card\"><h2>ACCUEIL PS5</h2><div id=\"tiles\">...</div></section>\n"
    " <section class=\"card wide\"><h2>RACCOURCIS</h2><div id=\"links\"></div></section>\n"
    " <section class=\"card\"><h2>ORBIT STORE</h2><div id=\"orbit\">...</div></section>\n"
    " <section class=\"card\"><h2>PAYLOAD</h2><div id=\"sys\">...</div></section>\n"
    "</main>\n"
    "<script>\n"
    "const $=id=>document.getElementById(id);\n"
    "const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n"
    "const H={'X-Menu':'1'};\n"
    "let note='';\n"
    "async function act(url){try{const r=await fetch(url,{method:'POST',headers:H});if(!r.ok)throw 0;note='Redémarre la PS5 pour appliquer.'}catch(e){note='Échec (sauvegarde ou base inaccessible).'}await load()}\n"
    "async function probe(){$('pr').textContent='Test en cours…';try{const r=await fetch('/api/probe',{method:'POST',headers:H});$('pr').textContent=(await r.json()).log}catch(e){$('pr').textContent='Échec'}}\n"
    "const setTile=(id,v)=>act('/api/set?id='+id+'&v='+(v?1:0));\n"
    "const setOrbit=v=>act('/api/orbit?v='+(v?1:0));\n"
    "const gb=b=>(b/1073741824).toFixed(1)+' Go';\n"
    "function tick(){const d=new Date();$('clock').textContent=d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});\n"
    " $('date').textContent=d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}\n"
    "setInterval(tick,1000);tick();\n"
    "const WX={0:'Ciel dégagé',1:'Plutôt dégagé',2:'Partiellement nuageux',3:'Couvert',45:'Brouillard',48:'Brouillard givrant',51:'Bruine',53:'Bruine',55:'Bruine',61:'Pluie faible',63:'Pluie',65:'Forte pluie',71:'Neige faible',73:'Neige',75:'Forte neige',80:'Averses',81:'Averses',82:'Fortes averses',95:'Orage'};\n"
    "async function weather(w){try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+w.lat+'&longitude='+w.lon+'&current=temperature_2m,weather_code&daily=temperature_2m_max,temperature_2m_min&timezone=auto');\n"
    " const j=await r.json();$('weather').innerHTML='<div class=\"big\">'+Math.round(j.current.temperature_2m)+'°C</div><div>'+(WX[j.current.weather_code]||'—')+'</div><small>'+esc(w.city)+' · min '+Math.round(j.daily.temperature_2m_min[0])+'° / max '+Math.round(j.daily.temperature_2m_max[0])+'°</small>'}\n"
    " catch(e){$('weather').innerHTML='<small>Météo indisponible (pas d\\'accès internet depuis cet appareil)</small>'}}\n"
    "let wxDone=false;\n"
    "async function load(){try{const r=await fetch('/api/info',{cache:'no-store'});const j=await r.json();\n"
    " $('ip').textContent=j.ip;\n"
    " if(j.storage.total>0){const used=j.storage.total-j.storage.free;$('storage').innerHTML='<div class=\"row\"><span>Espace libre</span><b>'+gb(j.storage.free)+'</b></div><div class=\"bar\"><i style=\"width:'+Math.round(used*100/j.storage.total)+'%\"></i></div><small>'+gb(used)+' utilisés sur '+gb(j.storage.total)+'</small>'}\n"
    " else $('storage').innerHTML='<small>Indisponible</small>';\n"
    " $('tiles').innerHTML=j.tiles.map(t=>'<div class=\"row\"><span>'+esc(t.label)+'</span><button class=\"sw '+(t.visible?'on':'')+'\" '+(t.found?'':'disabled ')+'title=\"'+(t.visible?'visible':'masqué')+'\" onclick=\"setTile(\\''+esc(t.id)+'\\','+(t.visible?0:1)+')\"></button></div>').join('')+'<small>'+note+'</small>';\n"
    " $('links').innerHTML=j.links.map(l=>'<a class=\"link\" target=\"_blank\" rel=\"noopener\" href=\"'+esc(l.url)+'\">'+esc(l.label)+'</a>').join('')||'<small>Aucun raccourci. Cree /data/dashboard_links.txt (une ligne par lien : Nom|http://...).</small>';\n"
    " const o=j.orbit;$('orbit').innerHTML=o.found?'<div class=\"row\"><span>Épinglé à gauche</span><button class=\"sw '+(o.pinned?'on':'')+'\" onclick=\"setOrbit('+(o.pinned?0:1)+')\"></button></div><small>Garde icon_menu.elf lancé pour maintenir le verrou.</small>':'<small>Non installé</small>';\n"
    " $('sys').innerHTML='<div class=\"row\"><span>Actif depuis</span><b>'+Math.floor(j.uptime/60)+' min</b></div><small>dashboard.elf '+j.version+'</small><div class=\"row\"><button onclick=\"probe()\">Diagnostic manettes / trophées</button></div><pre id=\"pr\" style=\"white-space:pre-wrap;font-size:12px;color:var(--mut)\"></pre>';\n"
    " if(!wxDone){wxDone=true;weather(j.weather)}\n"
    "}catch(e){$('ip').textContent='hors ligne'}}\n"
    "load();setInterval(load,10000);\n"
    "</script></body></html>\n"
    "\n";
